use infinitier_acm_decoder::{AcmDecoder, AcmInfo, OutputChannels};
use infinitier_datasource::DataSource;
use infinitier_test_utils::{get_assets_path, get_target_path};
use sha2::{Digest, Sha256};
use std::{fs, path::PathBuf};

/// Integration tests: decode every bundled ACM fixture and check the
/// SHA-256 hash of the produced WAV matches the reference output
/// generated by the original C libacm tool (acmtool).
fn decode_and_hash(acm_rel: &str) -> (String, AcmInfo) {
    let acm_path = get_assets_path().join("resources/ACM").join(acm_rel);

    let wav_rel = PathBuf::from(acm_rel).with_extension("wav");
    let wav_path = get_target_path().join("acm_test_output").join(&wav_rel);
    fs::create_dir_all(wav_path.parent().unwrap()).unwrap();

    let data = DataSource::new(acm_path.clone());
    let reader = data.reader().unwrap();

    let mut dec = AcmDecoder::open(reader, OutputChannels::Original)
        .unwrap_or_else(|e| panic!("cannot decode {}: {e}", acm_path.display()));

    println!(
        "{}: {} Hz, {} ch, {} samples",
        acm_rel,
        dec.info.rate,
        dec.info.channels,
        dec.info.total_values / dec.info.channels,
    );

    let info = dec.info.clone();

    dec.decode_to_file(&wav_path)
        .unwrap_or_else(|e| panic!("decode error in {}: {e}", acm_path.display()));

    let wav_bytes = fs::read(&wav_path).unwrap();
    let hash = Sha256::digest(&wav_bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();

    (hash, info)
}

// ── 2ch / 22050 Hz / A:7/16  (BG1) ──────────────────────────────────────────

/// `bg/Bf1j4.ACM` — Length: 0:00 Chans:2(2) Freq:22050 A:7/16 kbps:146
#[test]
fn test_bg_bf1j4() {
    let (got, _info) = decode_and_hash("bg/Bf1j4.ACM");
    assert_eq!(
        got, "18d02d5777bda38e06dc357a027a39cd39755f770b55c54517f1bbce5f7e44bf",
        "WAV hash mismatch for bg/Bf1j4.ACM",
    );
}

