    let (got, info) = decode_and_hash("bg2_ee/oh6200a.acm");
    assert_eq!(
        got, "c4593f4ddbd4c48ef2380879c7c0571d33d78fbe178f1d18bc15f59e2a769e95",
        "WAV hash mismatch for bg2ee/oh6200a.acm",
    );
